};

/********************************************** 	
 * 설명       : 조회버튼 클릭
 ***********************************************/
scwin.fn_Search = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var param = '';
    // 조회조건			
    param += "&{P}V_OP_INST_CD=" + $c.stf.getObjectValue(cmb_op_Inst_cd);
    param += "&{P}V_OP_BND_KIND=" + $c.stf.getObjectValue(cmb_op_bnd_kind);
    param += "&{P}V_OP_BND_TYP_CD=" + $c.stf.getObjectValue(cmb_op_bnd_typ_cd);
    param += "&{P}V_OP_LST_YN=" + $c.stf.getObjectValue(cmb_op_lst_yn);
    param += "&{P}V_OP_DLST_RSN=" + $c.stf.getObjectValue(cmb_op_dlst_rsn);
    param += "&{P}V_OP_GRT_CD=" + $c.stf.getObjectValue(cmb_op_grt_cd);
    param += "&{P}V_OP_NUSUAL_BND_TP_CD=" + $c.stf.getObjectValue(cmb_op_nusual_bnd_tp_cd);
    param += "&{P}V_OP_OPT_BND_CD=" + $c.stf.getObjectValue(cmb_op_opt_bnd_cd);
    param += "&{P}V_OP_INT_PAY_MTH=" + $c.stf.getObjectValue(cmb_op_int_pay_mth);
    param += "&{P}V_OP_RDMP_MTH=" + $c.stf.getObjectValue(cmb_op_rdmp_mth);
    param += "&{P}V_OP_ASS_LIQ_CD=" + $c.stf.getObjectValue(cmb_op_ass_liq_cd);
    param += "&{P}V_OP_PRE_AF_CD=" + $c.stf.getObjectValue(cmb_op_pre_af_cd);
    param += "&{P}V_OP_ISS_PR=" + $c.stf.getObjectValue(cmb_op_iss_pr);
    param += "&{P}V_OP_GRT_INST=" + $c.stf.getObjectValue(cmb_op_grt_inst);
    //param += "&{P}V_OP_REG_AGT="+ getObjectValue(cmb_op_reg_agt);
    param += "&{P}V_OP_RGHT_TP_CD=" + $c.stf.getObjectValue(cmb_op_rght_tp_cd);
    param += "&{P}V_OP_MAIN_CO=" + $c.stf.getObjectValue(cmb_op_main_co);
    param += "&{P}V_OP_TRST_INST=" + $c.stf.getObjectValue(cmb_op_trst_inst);
    param += "&{P}V_OP_CRDT_INST=" + $c.stf.getObjectValue(cmb_op_crdt_inst);
    param += "&{P}V_OP_CRDT_INST_GRAD=" + $c.stf.getObjectValue(cmb_op_crdt_inst_grad);
    param += "&{P}V_OP_FISCAL_MM=" + $c.stf.getObjectValue(cmb_op_fiscal_mm);
    //param += "&{P}V_OP_TAX_YN="+ getObjectValue(cmb_op_TaxYn);

    // 조건 값
    param += "&{P}V_WV_INST_CD=" + txb_Inst_cd.getValue();
    param += "&{P}V_WV_BND_KIND=" + $c.stf.getObjectValue(cmb_bnd_kind);
    param += "&{P}V_WV_BND_TYP_CD=" + txb_bnd_typ_cd.getValue();
    param += "&{P}V_WV_LST_YN=" + $c.stf.getObjectValue(cmb_lst_yn);
    param += "&{P}V_WV_DLST_RSN=" + txb_dlst_rsn.getValue();
    param += "&{P}V_WV_GRT_CD=" + $c.stf.getObjectValue(cmb_grt_cd);
    param += "&{P}V_WV_NUSUAL_BND_TP_CD=" + $c.stf.getObjectValue(cmb_nusual_bnd_tp_cd);
    param += "&{P}V_WV_OPT_BND_CD=" + $c.stf.getObjectValue(cmb_opt_bnd_cd);
    param += "&{P}V_WV_INT_PAY_MTH=" + $c.stf.getObjectValue(cmb_int_pay_mth);
    param += "&{P}V_WV_RDMP_MTH=" + $c.stf.getObjectValue(cmb_rdmp_mth);
    param += "&{P}V_WV_ASS_LIQ_CD=" + $c.stf.getObjectValue(cmb_ass_liq_cd);
    param += "&{P}V_WV_PRE_AF_CD=" + $c.stf.getObjectValue(cmb_pre_af_cd);
    //param += "&{P}V_WV_ISS_PR="+ txb_iss_pr.value;
    param += "&{P}V_WV_ISS_PR=" + $c.stf.getObjectValue(edt_iss_pr);
    param += "&{P}V_WV_RGHT_TP_CD=" + $c.stf.getObjectValue(cmb_rght_tp_cd);
    //param += "&{P}V_WV_REG_AGT="+ txb_reg_agt.value;
    param += "&{P}V_WV_GRT_INST=" + txb_grt_inst.getValue();
    param += "&{P}V_WV_MAIN_CO=" + txb_main_co.getValue();
    param += "&{P}V_WV_TRST_INST=" + txb_trst_inst.getValue();
    param += "&{P}V_WV_CRDT_INST=" + $c.stf.getObjectValue(cmb_crdt_inst);
    param += "&{P}V_WV_CRDT_INST_GRAD=" + $c.stf.getObjectValue(cmb_crdt_inst_grad);
    param += "&{P}V_WV_FISCAL_MM=" + $c.stf.getObjectValue(cmb_fiscal_mm);
    param += "&{P}V_WV_ISS_STRT_DD=" + $c.stf.getObjectValue(edt_iss_strt_dd);
    param += "&{P}V_WV_RDMP_STRT_DD=" + $c.stf.getObjectValue(edt_rdmp_strt_dd);
    param += "&{P}V_WV_LST_STRT_DD=" + $c.stf.getObjectValue(edt_lst_strt_dd);
    param += "&{P}V_WV_DIST_STRT_DD=" + $c.stf.getObjectValue(edt_dist_strt_dd);
    param += "&{P}V_WV_ISS_END_DD=" + $c.stf.getObjectValue(edt_iss_end_dd);
    param += "&{P}V_WV_RDMP_END_DD=" + $c.stf.getObjectValue(edt_rdmp_end_dd);
    param += "&{P}V_WV_LST_END_DD=" + $c.stf.getObjectValue(edt_lst_end_dd);
    param += "&{P}V_WV_DIST_END_DD=" + $c.stf.getObjectValue(edt_dist_end_dd);
    //param += "&{P}V_WV_TAX_YN="+ getObjectValue(cmb_TaxYn);

    //alert(getObjectValue(cmb_crdt_inst_grad));

    var dsNm = "";
    var qryId = "";
    var voDtsList;
    var voGrdList;
    if (vsTabSel == "1" || vsTabSel == "2") {
        if (vsTabSel == "1") {
            tab_Main.setSelectedTabIndex("2");
        }
        dsNm = 'BNS_LIST_BND_SRCH_ALL_LIST';
        qryId = 'lds.stf.bnslist_bnd_srch.select.listAll';
        voDtsList = dts_List1;
        voGrdList = grd_List1;
    } else if (vsTabSel == "3") {
        dsNm = 'BNS_LIST_BND_SRCH_ALL_MON_LIST';
        qryId = 'lds.stf.bnslist_bnd_srch.select.listallmon';
        voDtsList = dts_List2;
        voGrdList = grd_List2;
    }
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + dsNm;
    url += "&queryId=" + qryId;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += param;
    //voDtsList.ExtProp("RecordType") = "Huge";
    voDtsList.DataID = encodeURI(url);
    voDtsList.Reset();
    $c.cm.ShowWin(voGrdList);
    return url;
};



/********************************************** 	
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_Inst_cd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 	
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_Inst_cd, arrPar[0].ISUR_CD);
};

/********************************************** 
 * 설명       : 채권분류 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetBndClss = function(arrPar) {
    arrPar[0] = {
        BND_CLSS_CD: "",
        BND_TP_NM: ""
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 설명       : 채권분류 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetBndClss = function(arrPar) {
    $c.stf.setObjectValue(txb_bnd_typ_cd, arrPar[0].BND_CLSS_CD);
};

/********************************************** 	
 * 설명       : 상장페지 사유선택 (종목)  팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParDelistRsn = function(arrPar) {
    arrPar[0] = {
        BND_DELIST_CD: ""
    };
    return
