/********************************************** 	
 * 설명       : 상장페지 사유선택 (종목)  팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParDelistRsn = function(arrPar) {
    //arrPar[0].DELIST_RSN_DTL
    $c.stf.setObjectValue(txb_dlst_rsn, arrPar[0].BND_DELIST_CD);
};

/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: $c.stf.getObjectValue(scwin.vSelObj),
        INST_NM: $c.stf.getObjectValue(scwin.vSelObj),
        LBL_NM: '',
        INIT_TP_CD: scwin.v_G_initTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    if (typeof(arrPar[0].INST_CD) != 'undefined') {
        $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].INST_CD);
    }
};


/********************************************** 
 * 함수명   : fn_ShowInst
 * 설명       : 기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowInst = function(selObj) {
    scwin.fn_GetPar = fn_GetParInst;
    scwin.fn_SetPar = fn_SetParInst;

    //fn_PopInstSearch(selObj);

    if (scwin.v_G_initTpCd == "2") {
        $c.bns.fn_PopInstSearch(cmb_op_Inst_cd);
    } else if (scwin.v_G_initTpCd == "3") {
        $c.bns.fn_PopInstSearch(cmb_op_bnd_kind);
    } else if (scwin.v_G_initTpCd == "1") {
        $c.bns.fn_PopInstSearch(cmb_op_bnd_typ_cd);
    } else if (scwin.v_G_initTpCd == "5") {
        $c.bns.fn_PopInstSearch(cmb_op_lst_yn);
    }
};




