/********************************************** 
 * 함수명   : fn_btnExcel
 * 설명       : 엑셀작업
 ***********************************************/
scwin.fn_btnExcel = function() {
    var voDtsList;
    var vsTabSel = tab_Main.getSelectedTabIndex();
    if (vsTabSel == 3) {
        voDtsList = dts_List2;
    } else {
        voDtsList = dts_List1;
    }
    if (voDtsList.getTotalRow() > 0) {
        var today = $c.ut.cGetToday("yyyymmddhhmmss");
        if (vsTabSel == 3) {
            //파일형식 today_화면명.xls
            var xls_path = $c.session.getExcelDownPath() + "상장채권(상장기준)_" + today + ".xlsx";
            $c.data.downloadGridViewOffice(grd_List2, "sheet1", xls_path, 8, 0);
        } else {
            //파일형식 today_화면명.xls
            var xls_path = $c.session.getExcelDownPath() + "상장채권(전체)_" + today + ".xlsx";
            $c.data.downloadGridViewOffice(grd_List1, "sheet1", xls_path, 8, 0);
            //grd_List1.SaveExcel('', false, false, true, fileNm);
            //grd_List1.GridToExcel('', "", 8);

        }
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



