scwin.btn_Search_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Search > onclick
     * 설명      : 조회버튼 클릭
     ***********************************************/
    if ($c.stf.getObjectValue(cmb_lst_yn) == 'A') {
        $c.win.alert(" 상장여부가 [ALL] 인 경우 조회 할 수 없습니다. \n 자료가 필요하시면  ITSM으로 요청하시기 바랍니다.\n");
    } else if ($c.stf.getObjectValue(cmb_lst_yn) == 'D' || $c.stf.getObjectValue(cmb_lst_yn) == 'N') {
        //상장여부가 '폐지' or '비상장' 일 경우 날짜를 3년이내로 설정해야함
        if ($c.stf.getObjectValue(edt_iss_strt_dd) == "" && $c.stf.getObjectValue(edt_iss_end_dd) == "" &&
            $c.stf.getObjectValue(edt_rdmp_strt_dd) == "" && $c.stf.getObjectValue(edt_rdmp_end_dd) == "" &&
            $c.stf.getObjectValue(edt_lst_strt_dd) == "" && $c.stf.getObjectValue(edt_lst_end_dd) == "" &&
            $c.stf.getObjectValue(edt_dist_strt_dd) == "" && $c.stf.getObjectValue(edt_dist_end_dd) == "") {
            $c.win.alert(" 상장여부가 [상장폐지, 비상장] 인 경우 \n 날짜조건 (발행일, 상환일, 상장일, 상장폐지일)을 \n 하나 이상(3년 이내) 입력해야 합니다.");
        } else {
            //발행일
            if ($c.stf.getObjectValue(edt_iss_strt_dd) != "" || $c.stf.getObjectValue(edt_iss_end_dd) != "") {
                if ($c.stf.getObjectValue(edt_iss_strt_dd) == "" || $c.stf.getObjectValue(edt_iss_end_dd) == "") {
                    $c.win.alert("발행일의 검색 시작일과 종료일을 모두 선택해야 합니다.");
                    return;
                }
                if (($c.stf.getObjectValue(edt_iss_strt_dd) != "" && $c.stf.getObjectValue(edt_iss_end_dd) != "") && (eval($c.ut.cGetPlusYear(edt_iss_strt_dd.getValue(), 3)) < eval(edt_iss_end_dd.getValue()))) {
                    $c.win.alert("발행일의 검색 기간은 3년 이내로만 가능합니다.");
                    return;
                }
                scwin.fn_Search();
            }
            //상환일
            if ($c.stf.getObjectValue(edt_rdmp_strt_dd) != "" || $c.stf.getObjectValue(edt_rdmp_end_dd) != "") {
                if ($c.stf.getObjectValue(edt_rdmp_strt_dd) == "" || $c.stf.getObjectValue(edt_rdmp_end_dd) == "") {
                    $c.win.alert("상환일의 검색 시작일과 종료일을 모두 선택해야 합니다.");
                    return;
                }
                if (($c.stf.getObjectValue(edt_rdmp_strt_dd) != "" && $c.stf.getObjectValue(edt_rdmp_end_dd) != "") && (eval($c.ut.cGetPlusYear(edt_rdmp_strt_dd.getValue(), 3)) < eval(edt_rdmp_end_dd.getValue()))) {
                    $c.win.alert("상환일의 검색 기간은 3년 이내로만 가능합니다.");
                    return;
                }
                scwin.fn_Search();
            }
            //상장일
            if ($c.stf.getObjectValue(edt_lst_strt_dd) != "" || $c.stf.getObjectValue(edt_lst_end_dd) != "") {
                if ($c.stf.getObjectValue(edt_lst_strt_dd) == "" || $c.stf.getObjectValue(edt_lst_end_dd) == "") {
                    $c.win.alert("상장일의 검색 시작일과 종료일을 모두 선택해야 합니다.");
                    return;
                }
                if (($c.stf.getObjectValue(edt_lst_strt_dd) != "" && $c.stf.getObjectValue(edt_lst_end_dd) != "") && (eval($c.ut.cGetPlusYear(edt_lst_strt_dd.getValue(), 3)) < eval(edt_lst_end_dd.getValue()))) {
                    $c.win.alert("상장일의 검색 기간은 3년 이내로만 가능합니다.");
                    return;
                }
                scwin.fn_Search();
            }
            //상장폐지일
            if ($c.stf.getObjectValue(edt_dist_strt_dd) != "" || $c.stf.getObjectValue(edt_dist_end_dd) != "") {
                if ($c.stf.getObjectValue(edt_dist_strt_dd) == "" || $c.stf.getObjectValue(edt_dist_end_dd) == "") {
                    $c.win.alert("상장폐지일의 검색 시작일과 종료일을 모두 선택해야 합니다.");
                    return;
                }
                if (($c.stf.getObjectValue(edt_dist_strt_dd) != "" && $c.stf.getObjectValue(edt_dist_end_dd) != "") && (eval($c.ut.cGetPlusYear(edt_dist_strt_dd.getValue(), 3)) < eval(edt_dist_end_dd.getValue()))) {
                    $c.win.alert("상장폐지일의 검색 기간은 3년 이내로만 가능합니다.");
                    return;
                }
                scwin.fn_Search();
            }
        }
    } else {
        scwin.fn_Search();
    }
};
