scwin.grd_List1_OnDblClick = function(row, colid) {
    if (dts_List1.getTotalRow() == 0) return;
    if (row > 0) {
        scwin.vgStdCd = dts_List1.getCellData(row, "STD_CD");
        scwin.fn_GetPar = fn_GetParIsuDtlAndMktactDtl;
        $c.bns.fn_PopIsuDtlAndMktactDtl(grd_List1);
    }
};
