    ck_int_rt_decsn_misc_bas_int_cd.setValue(flag);
    ck_int_rt_decsn_misc_bas_int_nm.setValue(flag);
    ck_spd_sgn.setValue(flag);
    ck_int_rt_decsn_tm_cd.setValue(flag);
    ck_uplmt_coupn_rt.setValue(flag);
    ck_lwlmt_coupn_rt.setValue(flag);
    ck_int_rt_decsn_bas_dd.setValue(flag);
    //ck_int_rt_chg_seq.checked = flag;
    //ck_int_rt_chg_dd.checked = flag;

};
